{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "protocol",
      "alternatives": [
        "(df['f02'] == 'tcp') | ((df['f14']==0) & (df['f15']==0) & (df['f20']==0) & (df['f21']==0) & (df['f22']==0) & (df['f23']==0) & np.isclose(df['f24'], 0.0, rtol=1e-5, atol=1e-9) & np.isclose(df['f25'], 0.0, rtol=1e-5, atol=1e-9) & np.isclose(df['f26'], 0.0, rtol=1e-5, atol=1e-9))"
      ],
      "features": ["f02", "f14", "f15", "f20", "f21", "f22", "f23", "f24", "f25", "f26"],
      "rationale": "TCP-specific fields (retransmissions, window, sequence numbers, setup times) must be zero when the transaction protocol is not TCP."
    },
    {
      "id": "R2",
      "category": "protocol",
      "alternatives": [
        "(df['f03'] == 'http') | ((df['f29']==0) & (df['f30']==0) & (df['f39']==0))"
      ],
      "features": ["f03", "f29", "f30", "f39"],
      "rationale": "HTTP-specific fields (pipelined depth, uncompressed content size, HTTP method count) must be zero when the application protocol is not HTTP."
    },
    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "(df['f03'] == 'ftp') | ((df['f37']==0) & (df['f38']==0))"
      ],
      "features": ["f03", "f37", "f38"],
      "rationale": "FTP-specific fields (user/password access flag, command count) must be zero when the application protocol is not FTP."
    },
    {
      "id": "R4_tcp",
      "category": "protocol",
      "alternatives": [
        "(df['f02'] != 'tcp') | (df['f04'].isin(['ACC','CLO','CON','FIN','REQ','RST','TXD','URH','URN','-']))"
      ],
      "features": ["f02", "f04"],
      "rationale": "For TCP transactions, f04 (connection state) should be one of the TCP-related states or '-' if not used."
    },
    {
      "id": "R4_icmp",
      "category": "protocol",
      "alternatives": [
        "(df['f02'] != 'icmp') | (df['f04'].isin(['ECO','ECR','MAS','PAR','TST','-']))"
      ],
      "features": ["f02", "f04"],
      "rationale": "For ICMP transactions, f04 should be one of the ICMP type abbreviations or '-' if not used."
    },
    {
      "id": "R4_udp",
      "category": "protocol",
      "alternatives": [
        "(df['f02'] != 'udp') | (df['f04'] == '-')"
      ],
      "features": ["f02", "f04"],
      "rationale": "For UDP transactions, f04 is typically not used and should be '-'."
    },
    {
      "id": "R4_other",
      "category": "protocol",
      "alternatives": [
        "(df['f02'].isin(['tcp','icmp','udp'])) | (df['f04'] == '-')"
      ],
      "features": ["f02", "f04"],
      "rationale": "For protocols other than TCP, ICMP, or UDP, f04 should be '-' as it is not applicable."
    }
  ]
}
